 982	// Close kicks off the shutdown process of the transport. This should be called
 983	// only once on a transport. Once it is called, the transport should not be
 984	// accessed anymore.
 985	func (t *http2Client) Close(err error) {
 986		t.mu.Lock()
 987		// Make sure we only close once.
 988		if t.state == closing {
 989			t.mu.Unlock()
 990			return
 991		}
 992		if t.logger.V(logLevel) {
 993			t.logger.Infof("Closing: %v", err)
 994		}
 995		// Call t.onClose ASAP to prevent the client from attempting to create new
 996		// streams.
 997		if t.state != draining {
 998			t.onClose(GoAwayInvalid)
 999		}
1000		t.state = closing
1001		streams := t.activeStreams
1002		t.activeStreams = nil
1003		if t.kpDormant {
1004			// If the keepalive goroutine is blocked on this condition variable, we
1005			// should unblock it so that the goroutine eventually exits.
1006			t.kpDormancyCond.Signal()
1007		}
1008		t.mu.Unlock()
1009		// Per HTTP/2 spec, a GOAWAY frame must be sent before closing the
1010		// connection. See https://httpwg.org/specs/rfc7540.html#GOAWAY.
1011		t.controlBuf.put(&goAway{code: http2.ErrCodeNo, debugData: []byte("client transport shutdown"), closeConn: err})
1012		<-t.writerDone
1013		t.cancel()
1014		t.conn.Close()
1015		channelz.RemoveEntry(t.channelz.ID)
1016		// Append info about previous goaways if there were any, since this may be important
1017		// for understanding the root cause for this connection to be closed.
1018		_, goAwayDebugMessage := t.GetGoAwayReason()
1019	
1020		var st *status.Status
1021		if len(goAwayDebugMessage) > 0 {
1022			st = status.Newf(codes.Unavailable, "closing transport due to: %v, received prior goaway: %v", err, goAwayDebugMessage)
1023			err = st.Err()
1024		} else {
1025			st = status.New(codes.Unavailable, err.Error())
1026		}
1027	
1028		// Notify all active streams.
1029		for _, s := range streams {
1030			t.closeStream(s, err, false, http2.ErrCodeNo, st, nil, false)
1031		}
1032		for _, sh := range t.statsHandlers {
1033			connEnd := &stats.ConnEnd{
1034				Client: true,
1035			}
1036			sh.HandleConn(t.ctx, connEnd)
1037		}
