1040	// GracefulClose sets the state to draining, which prevents new streams from
1041	// being created and causes the transport to be closed when the last active
1042	// stream is closed.  If there are no active streams, the transport is closed
1043	// immediately.  This does nothing if the transport is already draining or
1044	// closing.
1045	func (t *http2Client) GracefulClose() {
1046		t.mu.Lock()
1047		// Make sure we move to draining only from active.
1048		if t.state == draining || t.state == closing {
1049			t.mu.Unlock()
1050			return
1051		}
1052		if t.logger.V(logLevel) {
1053			t.logger.Infof("GracefulClose called")
1054		}
1055		t.onClose(GoAwayInvalid)
1056		t.state = draining
1057		active := len(t.activeStreams)
1058		t.mu.Unlock()
1059		if active == 0 {
1060			t.Close(connectionErrorf(true, nil, "no active streams left to process while draining"))
1061			return
1062		}
1063		t.controlBuf.put(&incomingGoAway{})
1064	}
